async function resolvePanelTemplate(spindle2, template, chatId, userId, characterId2) {
  if (typeof template !== "string" || template.length > 1e5 || typeof chatId !== "string" || !chatId)
    throw new Error("Invalid panel template or chat.");
  if (!spindle2.macros?.resolve)
    throw new Error("This host does not provide template macro resolution. Paste rendered HTML instead.");
  const result = await spindle2.macros.resolve(template, { chatId, userId, commit: false, ...characterId2 ? { characterId: characterId2 } : {} });
  if (result.text.length > 1e5)
    throw new Error("Resolved template exceeds 100 KB.");
  if (result.diagnostics?.length)
    throw new Error(result.diagnostics.map((d) => d.message).join("; ").slice(0, 500));
  return result.text;
}

